const role=$input.first().json.body.data.fields[3].value
const resume = $('PDFco API').first().json.body
  .replace(/\\n/g, '\n')      // turn \n strings into actual line breaks
  .replace(/\\t/g, ' ')       // turn \t (tabs) into spaces
  .replace(/\s+/g, ' ')       // collapse multiple spaces into one
  .trim();                     // remove leading/trailing spaces
const jd=$input.first().json.body.data.fields[2].value
  .replace(/\\n/g, '\n')
  .replace(/\\t/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{
  json: {
    resume_text: resume,
    job_description: jd,
    role: role
  }
}];

const resume=$input.first().json.resume_text
const role = $input.first().json.role
if (role.toLowerCase().trim() === 'none') {
  return [{ json: { role: 'role not available' } }];
}

return [{ json: { role: role.toLowerCase().trim(),
                  resume_text: resume
                } }];

