const role= $input.first().json.role
const resume=$input.first().json.resume_text
let matched = null;
for (const benchmark of Object.keys(benchmarks)) {
  const words = role.split(/\s+/);
  if (words.some(word =>  benchmark.toLowerCase().includes(word.toLowerCase())
  )) {
    matched = benchmark;
    break;
  }
}
return[{
  json: {
    role:role,
    benchmark: benchmarks,
    matched_role:matched,
    resume_body:resume
  }
}];

